def calculate_sum(numbers):
  """Calculates the sum of a list of numbers."""
  total = 0
  for number in numbers:
    total = add_to_total(total, number)
  return total


def add_to_total(current_total, number):
  """Adds a single number to the current total."""
  return current_total + number


def is_list_empty(numbers):
  """Checks if a list of numbers is empty."""
  return len(numbers) == 0


def get_sum_for_empty_list():
  """Returns the sum for an empty list."""
  return 0


def sum_list(numbers):
  """
  Takes a list of numbers and returns their sum.
  For example, sum_list([1, 2, 3, 4]) should return 10,
  and sum_list([]) should return 0.
  """
  if is_list_empty(numbers):
    return get_sum_for_empty_list()
  else:
    return calculate_sum(numbers)


def test_sum_list():
  """Tests the sum_list function with example cases."""
  assert sum_list([1, 2, 3, 4]) == 10
  assert sum_list([]) == 0
  assert sum_list([5]) == 5
  assert sum_list([-1, 1]) == 0
  assert sum_list([0, 0, 0]) == 0

test_sum_list()

