import re


def split_into_words(sentence):
    return re.findall(r'\b\w+\b', sentence)


def get_word_length(word):
    return len(word)


def find_max_length(lengths):
    if not lengths:
        return 0
    return max(lengths)


def find_longest_word_index(words, max_len):
    for i, word in enumerate(words):
        if len(word) == max_len:
            return i
    return -1


def find_longest_word(sentence):
    words = split_into_words(sentence)
    if not words:
        return ""

    word_lengths = [get_word_length(word) for word in words]
    max_len = find_max_length(word_lengths)
    longest_word_idx = find_longest_word_index(words, max_len)

    return words[longest_word_idx] if longest_word_idx != -1 else ""

