def _is_upper(char):
    return 'A' <= char <= 'Z'


def _is_lower(char):
    return 'a' <= char <= 'z'


def _shift_char(char, shift, start_char, alphabet_size):
    return chr(start_char + (ord(char) - start_char + shift) % alphabet_size)


def _process_char(char, shift):
    if _is_upper(char):
        return _shift_char(char, shift, ord('A'), 26)
    elif _is_lower(char):
        return _shift_char(char, shift, ord('a'), 26)
    else:
        return char


def caesar_cipher_encrypt(text, shift):
    result = ""
    for char in text:
        result += _process_char(char, shift)
    return result


def main():
    assert caesar_cipher_encrypt('abc', 1) == 'bcd'
    assert caesar_cipher_encrypt('xyz', 3) == 'abc'
