def reverse_list_in_place(word_list):
    word_list.reverse()

def join_words_to_sentence(word_list):
    return ' '.join(word_list)

def reverse_words(sentence):
    words = split_sentence_into_words(sentence)
    reversed_words = get_reversed_words(words)
    result_sentence = join_words_to_sentence(reversed_words)
    return result_sentence

def get_reversed_words(words):
    reverse_list_in_place(words)
    return words

