def binary_to_decimal(binary_string):
    decimal_value = 0
    power = 0
    reversed_string = reverse_string(binary_string)
    for digit in reversed_string:
        decimal_value += convert_digit_to_int(digit) * (2 ** power)
        power = increment_power(power)
    return decimal_value


def reverse_string(s):
    return s[::-1]


def convert_digit_to_int(digit):
    return int(digit)


def increment_power(current_power):
    return current_power + 1


def is_binary_digit(char):
    return char == '0' or char == '1'


def validate_binary_string(binary_string):
    for char in binary_string:
        if not is_binary_digit(char):
            raise ValueError("Invalid binary string: contains non-binary digits.")
    return True

